def transform(grid):
    h, w = len(grid), len(grid[0])

    # The solid-color separator lines divide the grid into independent cells.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
    ]

    def blocks(size, separators):
        result = []
        start = 0
        for pos in separators:
            if pos > start:
                result.append((start, pos))
            start = pos + 1
        if start < size:
            result.append((start, size))
        return result

    row_blocks = blocks(h, sep_rows)
    col_blocks = blocks(w, sep_cols)

    output = []
    for r0, r1 in row_blocks:
        out_row = []
        for c0, c1 in col_blocks:
            counts = {}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    counts[color] = counts.get(color, 0) + 1
            background = max(counts, key=counts.get)
            marks = sum(n for color, n in counts.items() if color != background)
            out_row.append(1 if marks >= 2 else background)
        output.append(out_row)
    return output
